import { Component, OnInit } from '@angular/core';
import {AuthService, Korisnik} from "../../services/auth.service";
=
@Component({
  selector: 'app-profile',
  templateUrl: './profile.component.html',
  styleUrls: ['./profile.component.css']
})
export class ProfileComponent implements OnInit {
  public imagePath = 'assets/user.png';
  public user: Korisnik | null = null;

  constructor(private authService: AuthService) { }

  ngOnInit(): void {
    this.authService.getCurrentUser().subscribe({
      next: (data) => this.user = data,
      error: (err) => console.error(err)
    });
  }
}
<div class="profile-page" *ngIf="user">
  <div class="profile-card">
    <!-- Avatar -->
    <div class="profile-avatar">
      <img [src]="imagePath" alt="User Avatar">
    </div>

    <h3 class="profile-title">Profil</h3>

    <div class="profile-field">
      <label>First Name</label>
      <input type="text" [value]="user.ime" readonly>
    </div>
    <div class="profile-field">
      <label>Last Name</label>
      <input type="text" [value]="user.prezime" readonly>
    </div>
    <div class="profile-field">
      <label>Email</label>
      <input type="email" [value]="user.email" readonly>
    </div>
    <div class="profile-field">
      <label>Role</label>
      <input type="text" [value]="user.rola" readonly>
    </div>
  </div>
</div>
